 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Each nonzero cell in the top stripe sends a ray downward. If its color
    # appears elsewhere, the ray stops at that marker's row and joins it.
    for c, color in enumerate(grid[0]):
        if color == 0:
            continue
        markers = [(r, x) for r in range(1, h) for x in range(w) if grid[r][x] == color]
        if markers:
            r, x = markers[0]
            end = r
            for rr in range(1, end + 1):
                out[rr][c] = color
            for cc in range(min(c, x), max(c, x) + 1):
                out[r][cc] = color
        else:
            for rr in range(1, h):
                out[rr][c] = color
    return out
